class Inventory:
    def __init__(self):
        self._stock: dict[str, int] = {}

    def add(self, sku: str, qty: int) -> None:
        if qty <= 0:
            raise ValueError("qty must be positive")
        self._stock[sku] = self._stock.get(sku, 0) + qty

    def remove(self, sku: str, qty: int) -> bool:
        if qty <= 0:
            raise ValueError("qty must be positive")
        if self._stock.get(sku, 0) < qty:
            return False
        self._stock[sku] -= qty
        return True

    def count(self, sku: str) -> int:
        return self._stock.get(sku, 0)

class Inventory:
    def __init__(self):
        self._stock: dict[str, int] = {}
        self._reservations: dict[str, tuple[str, int]] = {}  # order_id -> (sku, qty)

    def _reserved(self, sku: str) -> int:
        return sum(q for s, q in self._reservations.values() if s == sku)

    def add(self, sku: str, qty: int) -> None:
        if qty <= 0:
            raise ValueError("qty must be positive")
        self._stock[sku] = self._stock.get(sku, 0) + qty

    def available(self, sku: str) -> int:
        return self._stock.get(sku, 0) - self._reserved(sku)

    def remove(self, sku: str, qty: int) -> bool:
        if qty <= 0:
            raise ValueError("qty must be positive")
        if self.available(sku) < qty:
            return False
        self._stock[sku] -= qty
        return True

    def count(self, sku: str) -> int:
        return self._stock.get(sku, 0)

    def reserve(self, order_id: str, sku: str, qty: int) -> bool:
        if qty <= 0:
            raise ValueError("qty must be positive")
        if order_id in self._reservations or self.available(sku) < qty:
            return False
        self._reservations[order_id] = (sku, qty)
        return True

    def cancel(self, order_id: str) -> bool:
        return self._reservations.pop(order_id, None) is not None

    def fulfill(self, order_id: str) -> bool:
        res = self._reservations.pop(order_id, None)
        if res is None:
            return False
        sku, qty = res
        self._stock[sku] -= qty
        return True

