class Inventory:
    def __init__(self, reservation_ttl: int | None = None):
        self._ttl = reservation_ttl
        self._stock: dict[str, int] = {}
        # order_id -> (sku, qty, created_at)
        self._reservations: dict[str, tuple[str, int, int]] = {}

    def _expire(self, now: int) -> None:
        if self._ttl is None:
            return
        expired = [o for o, (_, _, t) in self._reservations.items() if now >= t + self._ttl]
        for order_id in expired:
            del self._reservations[order_id]

    def _reserved(self, sku: str) -> int:
        return sum(q for s, q, _ in self._reservations.values() if s == sku)

    def add(self, sku: str, qty: int, now: int = 0) -> None:
        if qty <= 0:
            raise ValueError("qty must be positive")
        self._stock[sku] = self._stock.get(sku, 0) + qty

    def available(self, sku: str, now: int = 0) -> int:
        self._expire(now)
        return self._stock.get(sku, 0) - self._reserved(sku)

    def remove(self, sku: str, qty: int, now: int = 0) -> bool:
        if qty <= 0:
            raise ValueError("qty must be positive")
        if self.available(sku, now) < qty:
            return False
        self._stock[sku] -= qty
        return True

    def count(self, sku: str) -> int:
        return self._stock.get(sku, 0)

    def reserve(self, order_id: str, sku: str, qty: int, now: int = 0) -> bool:
        if qty <= 0:
            raise ValueError("qty must be positive")
        self._expire(now)
        if order_id in self._reservations or self.available(sku, now) < qty:
            return False
        self._reservations[order_id] = (sku, qty, now)
        return True

    def cancel(self, order_id: str, now: int = 0) -> bool:
        self._expire(now)
        return self._reservations.pop(order_id, None) is not None

    def apply(self, ops: list[tuple], now: int = 0) -> bool:
        """Apply ops atomically: all succeed, or the inventory is left unchanged."""
        handlers = {
            "add": lambda a: self.add(*a, now=now) is None,
            "remove": lambda a: self.remove(*a, now=now),
            "reserve": lambda a: self.reserve(*a, now=now),
            "cancel": lambda a: self.cancel(*a, now=now),
            "fulfill": lambda a: self.fulfill(*a, now=now),
        }
        self._expire(now)
        snapshot = (dict(self._stock), dict(self._reservations))
        try:
            ok = all(handlers[op[0]](op[1:]) for op in ops)
        except (KeyError, ValueError, TypeError):
            ok = False
        if not ok:
            self._stock, self._reservations = snapshot
        return ok

    def fulfill(self, order_id: str, now: int = 0) -> bool:
        self._expire(now)
        res = self._reservations.pop(order_id, None)
        if res is None:
            return False
        sku, qty, _ = res
        self._stock[sku] -= qty
        return True
